FluxMainWindow::FluxMainWindow(QWidget* parent):QMainWindow(parent),m_document(new FluxDocument),m_playTimer(new QTimer(this)){
    setWindowTitle("Flux Studio — Home");resize(1680,1040);setMinimumSize(1180,760);setDockNestingEnabled(true);
    m_canvas=new FluxCanvas(this);m_canvas->setDocument(m_document);m_stack=new QStackedWidget(this);m_stack->setObjectName("mainStack");m_home=new QWidget(m_stack);m_stack->addWidget(m_home);m_stack->addWidget(m_canvas);setCentralWidget(m_stack);
    connect(m_canvas,&FluxCanvas::documentChanged,this,&FluxMainWindow::markModified);connect(m_canvas,&FluxCanvas::cursorInfoChanged,this,[this](const QString&s){if(m_cursorLabel)m_cursorLabel->setText(s);});connect(m_canvas,&FluxCanvas::zoomChanged,this,&FluxMainWindow::updateZoomLabel);connect(m_canvas,&FluxCanvas::wheelRequested,this,[this](const QPoint&p){if(m_wheel)m_wheel->openAt(p);});
    connect(m_playTimer,&QTimer::timeout,this,[this]{int f=m_document->frame()+1;if(f>=m_document->frameCount())f=m_playing?0:m_document->frameCount()-1;m_document->setFrame(f);m_canvas->update();});m_playTimer->setInterval(1000/24);
    buildHome();buildMenus();buildTopBar();buildToolRail();buildDocks();m_wheel=new FluxWheel(this);connect(m_wheel,&FluxWheel::commandTriggered,this,[this](int i){switch(i){case 0:m_canvas->setTool("Brush");break;case 1:m_canvas->setTool("Pencil");break;case 2:m_canvas->setTool("Eraser");break;case 3:m_canvas->setTool("Ink");break;case 4:chooseColor();break;case 5:m_document->setFrame(qMax(0,m_document->frame()-1));m_canvas->update();break;case 6:m_document->setFrame(qMin(m_document->frameCount()-1,m_document->frame()+1));m_canvas->update();break;default:fitCanvas();break;}});
    m_autosavePath=QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)+QStringLiteral("/recovery.flux");auto*timer=new QTimer(this);timer->setInterval(30000);connect(timer,&QTimer::timeout,this,&FluxMainWindow::autosave);timer->start();restoreLastSession();m_stack->setCurrentWidget(m_home);for(auto*d:findChildren<QDockWidget*>())d->hide();if(m_topBar)m_topBar->hide();if(m_toolRail)m_toolRail->hide();polish();
}
FluxMainWindow::~FluxMainWindow(){autosave();delete m_document;}

