    auto*recentFrame=new QFrame(m_home);recentFrame->setObjectName("homeRecent");auto*recentLay=new QVBoxLayout(recentFrame);recentLay->setContentsMargins(18,16,18,16);auto*rh=new QHBoxLayout;rh->addWidget(label("RECENT PROJECTS","section"));rh->addStretch();auto*refresh=new QPushButton("Refresh");refresh->setObjectName("tinyButton");rh->addWidget(refresh);recentLay->addLayout(rh);auto*recent=new QListWidget(recentFrame);recent->setObjectName("homeRecentList");recentLay->addWidget(recent,1);root->addWidget(recentFrame,1);
    auto populate=[recent](){recent->clear();const auto paths=FluxWorkflow::recentProjects(12);if(paths.isEmpty()){auto*i=new QListWidgetItem("No recent projects yet — create your first document.");i->setFlags(Qt::NoItemFlags);recent->addItem(i);return;}for(const auto&p:paths){if(!QFileInfo::exists(p))continue;auto*i=new QListWidgetItem(QFileInfo(p).completeBaseName());i->setData(Qt::UserRole,p);i->setToolTip(p);recent->addItem(i);}if(recent->count()==0){auto*i=new QListWidgetItem("No valid recent projects.");i->setFlags(Qt::NoItemFlags);recent->addItem(i);}};populate();connect(refresh,&QPushButton::clicked,populate);connect(create,&QPushButton::clicked,this,&FluxMainWindow::newProject);connect(open,&QPushButton::clicked,this,&FluxMainWindow::openProject);connect(recent,&QListWidget::itemDoubleClicked,this,[this](QListWidgetItem*i){const auto p=i?i->data(Qt::UserRole).toString():QString();if(!p.isEmpty())loadProjectPath(p);});connect(brush,&QPushButton::clicked,this,&FluxMainWindow::openBrushEditor);connect(compose,&QPushButton::clicked,this,[this]{enterWorkspace();for(auto*d:findChildren<QDockWidget*>())if(d->windowTitle()=="Compose")d->raise();});connect(animate,&QPushButton::clicked,this,&FluxMainWindow::enterWorkspace);auto*foot=new QHBoxLayout;foot->addWidget(label("DRAW  →  ANIMATE  →  COMPOSE  →  EXPORT","footer"));foot->addStretch();foot->addWidget(label("Ctrl+N  New   •   Ctrl+O  Open   •   Ctrl+K  Commands","hint"));root->addLayout(foot);
